    31	@Service
    32	@Transactional(noRollbackFor = ErroNegocio.class)
    33	public class PedidoServico {
    35	    private static final Duration PRAZO_PAGAMENTO = Duration.ofHours(48);
    37	    private final CalculadoraResumo calculadora;
    38	    private final PedidoRepositorio pedidos;
    39	    private final ClienteRepositorio clientes;
    40	    private final ProdutoRepositorio produtos;
