    46	    public PedidoServico(CalculadoraResumo calculadora, PedidoRepositorio pedidos, ClienteRepositorio clientes,
    47	            ProdutoRepositorio produtos, List<AcaoPagamentoConfirmado> aoPagar, List<AcaoCancelamento> aoCancelar,
    48	            List<Notificador> notificadores, Clock relogio) {
    49	        this.calculadora = calculadora;
    50	        this.pedidos = pedidos;
    51	        this.clientes = clientes;
    52	        this.produtos = produtos;
    53	        this.aoPagar = aoPagar;
    54	        this.aoCancelar = aoCancelar;
    55	        this.notificadores = notificadores;
    56	        this.relogio = relogio;
    57	    }
    59	    @Transactional(readOnly = true)
    60	    public Resumo resumo(CompraRequest compra) {
    61	        return calculadora.calcular(compra);
    62	    }
    64	    public Pedido registrar(CompraRequest compra) {
    65	        Resumo resumo = calculadora.calcular(compra);
    66	        clientes.criarSeAusente(compra.cliente().cpf(), compra.cliente().email());
    67	        Pedido pedido = new Pedido(
    68	                UUID.randomUUID().toString(),
    69	                compra.cliente().cpf(),
    70	                compra.cliente().email(),
    71	                compra.cep(),
    72	                compra.regiao(),
    73	                compra.modalidadeEntrega(),
    74	                compra.cupom(),
    75	                compra.formaPagamento(),
    76	                compra.nivelClube(),
    77	                SituacaoPedido.AGUARDANDO_PAGAMENTO,
    78	                relogio.instant().truncatedTo(ChronoUnit.SECONDS),
    79	                resumo,
    80	                CalculadoraResumo.itensDe(compra),
    81	                null,
    82	                null);
    83	        pedidos.inserir(pedido);
    84	        return pedido;
    85	    }
    87	    @Transactional(readOnly = true)
    88	    public Pedido consultar(String id) {
    89	        return pedidos.buscar(id).orElseThrow(() -> new ErroNegocio(CodigoErro.PEDIDO_NAO_ENCONTRADO));
    90	    }
    92	    public Pedido pagar(String id, String idTransacao, Instant pagoEm) {
    93	        Pedido pedido = travar(id);
    94	        if (idTransacao == null || idTransacao.isBlank()) {
    95	            throw new ErroNegocio(CodigoErro.PEDIDO_INVALIDO);
    96	        }
    97	        if (pedido.idTransacao() != null && pedido.idTransacao().equals(idTransacao)
    98	                && pedido.situacao() != SituacaoPedido.CANCELADO) {
    99	            return pedido;
   100	        }
   101	        if (pedido.situacao() != SituacaoPedido.AGUARDANDO_PAGAMENTO) {
   102	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   103	        }
   104	        Instant momento = pagoEm != null ? pagoEm : relogio.instant();
   105	        if (momento.isAfter(pedido.criadoEm().plus(PRAZO_PAGAMENTO))) {
   106	            cancelar(pedido, false);
   107	            throw new ErroNegocio(CodigoErro.PEDIDO_EXPIRADO);
   108	        }
   109	        if (!produtos.baixarEstoque(pedido.itens())) {
   110	            cancelar(pedido, false);
   111	            throw new ErroNegocio(CodigoErro.ESTOQUE_INSUFICIENTE_PAGAMENTO);
   112	        }
   113	        pedidos.registrarPagamento(id, idTransacao);
   114	        Pedido pago = pedidos.buscar(id).orElseThrow();
   115	        aoPagar.forEach(a -> a.executar(pago));
   116	        return pago;
   117	    }
   119	    public Pedido enviar(String id, String codigoRastreio) {
   120	        Pedido pedido = travar(id);
   121	        if (pedido.situacao() != SituacaoPedido.PAGO) {
   122	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   123	        }
   124	        if (codigoRastreio == null || codigoRastreio.isBlank()) {
   125	            throw new ErroNegocio(CodigoErro.PEDIDO_INVALIDO);
   126	        }
   127	        pedidos.registrarEnvio(id, codigoRastreio);
   128	        Pedido enviado = pedidos.buscar(id).orElseThrow();
   129	        notificadores.forEach(n -> n.notificar(TipoAviso.PEDIDO_ENVIADO, enviado));
   130	        return enviado;
   131	    }
   133	    public Pedido entregar(String id) {
   134	        Pedido pedido = travar(id);
   135	        if (pedido.situacao() != SituacaoPedido.ENVIADO) {
   136	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   137	        }
   138	        pedidos.atualizarSituacao(id, SituacaoPedido.ENTREGUE);
   139	        return pedidos.buscar(id).orElseThrow();
   140	    }
   142	    public Pedido cancelar(String id) {
   143	        Pedido pedido = travar(id);
   144	        if (pedido.situacao() != SituacaoPedido.AGUARDANDO_PAGAMENTO && pedido.situacao() != SituacaoPedido.PAGO) {
   145	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   146	        }
   147	        cancelar(pedido, pedido.situacao() == SituacaoPedido.PAGO);
   148	        return pedidos.buscar(id).orElseThrow();
   149	    }
   151	    private void cancelar(Pedido pedido, boolean estavaPago) {
   152	        pedidos.atualizarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
   153	        aoCancelar.forEach(a -> a.executar(pedido, estavaPago));
   154	    }
   156	    private Pedido travar(String id) {
   157	        return pedidos.buscarComTrava(id).orElseThrow(() -> new ErroNegocio(CodigoErro.PEDIDO_NAO_ENCONTRADO));
   158	    }
