   134	        Pedido pedido = travar(id);
   135	        if (pedido.situacao() != SituacaoPedido.ENVIADO) {
   136	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   137	        }
   138	        pedidos.atualizarSituacao(id, SituacaoPedido.ENTREGUE);
   139	        return pedidos.buscar(id).orElseThrow();
   140	    }
   142	    public Pedido cancelar(String id) {
   143	        Pedido pedido = travar(id);
   144	        if (pedido.situacao() != SituacaoPedido.AGUARDANDO_PAGAMENTO && pedido.situacao() != SituacaoPedido.PAGO) {
   145	            throw new ErroNegocio(CodigoErro.OPERACAO_NAO_PERMITIDA);
   146	        }
   147	        cancelar(pedido, pedido.situacao() == SituacaoPedido.PAGO);
