=== entrega/TransLogClient.java
     1	package com.loja.pedidos.entrega;
    18	@Component
    19	public class TransLogClient {
    21	    private static final Duration LIMITE = Duration.ofSeconds(2);
    23	    private final String baseUrl;
    24	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(LIMITE).build();
    25	    private final JsonMapper json = JsonMapper.builder().build();
    27	    public TransLogClient(@Value("${translog.url}") String baseUrl) {
    28	        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    29	    }
    31	    public RespostaTransLog cotar(String cep, int pesoGramas, String servico) {
    32	        CompletableFuture<HttpResponse<String>> futuro = null;
    33	        try {
    34	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + cep + "&weight_g=" + pesoGramas + "&service=" + servico);
    35	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(LIMITE).GET().build();
    36	            futuro = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    37	            HttpResponse<String> resposta = futuro.get(LIMITE.toMillis(), TimeUnit.MILLISECONDS);
    38	            if (resposta.statusCode() != 200) {
    39	                return new RespostaTransLog.ForaDoAr();
    40	            }
    41	            return interpretar(json.readTree(resposta.body()));
    42	        } catch (InterruptedException e) {
    43	            Thread.currentThread().interrupt();
    44	            return new RespostaTransLog.ForaDoAr();
    45	        } catch (Exception e) {
    46	            return new RespostaTransLog.ForaDoAr();
    47	        } finally {
    48	            if (futuro != null) {
    49	                futuro.cancel(true);
    50	            }
    51	        }
    52	    }
    54	    private RespostaTransLog interpretar(JsonNode no) {
    55	        if (no == null || !no.isObject()) {
    56	            return new RespostaTransLog.ForaDoAr();
    57	        }
    58	        JsonNode erro = no.get("error");
    59	        if (erro != null) {
    60	            return erro.isString() && "ZIP_NOT_SERVED".equals(erro.stringValue())
    61	                    ? new RespostaTransLog.CepNaoAtendido()
    62	                    : new RespostaTransLog.ForaDoAr();
    63	        }
    64	        JsonNode preco = no.get("price_cents");
    65	        JsonNode horas = no.get("eta_hours");
    66	        if (preco == null || horas == null || !preco.isIntegralNumber() || !horas.isIntegralNumber()
    67	                || !preco.canConvertToInt() || !horas.canConvertToInt()
    68	                || preco.intValue() < 0 || horas.intValue() < 0) {
    69	            return new RespostaTransLog.ForaDoAr();
    70	        }
    71	        return new RespostaTransLog.Preco(preco.intValue(), horas.intValue());
    72	    }
    73	}
