    62	        List<ItemPedido> ordenados = itens.stream().sorted(Comparator.comparing(ItemPedido::sku)).toList();
    63	        for (ItemPedido item : ordenados) {
    64	            Integer estoque = jdbc.sql("SELECT estoque FROM produto WHERE sku = :sku FOR UPDATE")
    65	                    .param("sku", item.sku()).query(Integer.class).optional().orElse(null);
    66	            if (estoque == null || estoque < item.quantidade()) {
    67	                return false;
    68	            }
    69	        }
    70	        for (ItemPedido item : ordenados) {
    71	            jdbc.sql("UPDATE produto SET estoque = estoque - :q WHERE sku = :sku")
    72	                    .param("q", item.quantidade()).param("sku", item.sku()).update();
    73	        }
    74	        return true;
    75	    }
    77	    public void devolverEstoque(List<ItemPedido> itens) {
    78	        for (ItemPedido item : itens.stream().sorted(Comparator.comparing(ItemPedido::sku)).toList()) {
    79	            jdbc.sql("UPDATE produto SET estoque = estoque + :q WHERE sku = :sku")
    80	                    .param("q", item.quantidade()).param("sku", item.sku()).update();
    81	        }
    82	    }
